<script setup>
import { computed } from 'vue'
import DOMPurify from 'dompurify'
import { copyToClipboard, useQuasar } from 'quasar'
import { parseAssistantBlocks } from '../services/admin-assistant.js'
import AssistantFile from './AssistantFile.vue'
const props = defineProps({ message: { type: Object, required: true } })
const $q = useQuasar()
const blocks = computed(() => parseAssistantBlocks(props.message.text))
const escape = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))
function prose(value) {
  const html = escape(value).replace(/^###\s+(.+)$/gm, '<h4>$1</h4>').replace(/^##?\s+(.+)$/gm, '<h3>$1</h3>').replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>').replace(/`([^`\n]+)`/g, '<code>$1</code>').replace(/\[([^\]\n]+)\]\((https:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>')
  return DOMPurify.sanitize(html, { ALLOWED_TAGS: ['h3','h4','strong','code','a'], ALLOWED_ATTR: ['href','target','rel'] })
}
async function copy(text) { try { await copyToClipboard(text); $q.notify({message:'Copiado.',position:'top',timeout:1200}) } catch { $q.notify({type:'warning',message:'Não foi possível copiar.'}) } }
function download(block) {
  const type = /json/i.test(block.language) ? 'application/json' : 'text/plain', extension = /json/i.test(block.language) ? 'json' : /html|css|md|csv/i.test(block.language) ? block.language.toLowerCase() : 'txt'
  const url = URL.createObjectURL(new Blob([block.text], {type})), link = document.createElement('a'); link.href=url;link.download='aito-ia.'+extension;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000)
}
</script>
<template><article class="assistant-message" :class="{'assistant-message--user':message.role==='user'}"><div class="assistant-message__by"><q-icon :name="message.role==='user'?'person':'auto_awesome'"/><strong>{{message.role==='user'?'Você':'Aito I.A'}}</strong><time v-if="message.at">{{new Date(message.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}}</time></div><div class="assistant-message__content"><template v-for="(block,index) in blocks" :key="index"><section v-if="block.type==='code'" class="assistant-code"><header><span>{{block.language}}</span><q-btn flat dense no-caps icon="content_copy" label="Copiar" @click="copy(block.text)"/><q-btn flat dense no-caps icon="download" label="Baixar" @click="download(block)"/></header><pre><code>{{block.text}}</code></pre></section><div v-else class="assistant-prose" v-html="prose(block.text)"/></template><div v-if="message.attachments?.length" class="assistant-message__files"><AssistantFile v-for="file in message.attachments" :key="file.id" :file="file"/></div><q-btn v-if="message.role==='assistant'&&message.text" class="assistant-message__copy" flat round dense icon="content_copy" aria-label="Copiar resposta" @click="copy(message.text)"/></div></article></template>
<style scoped>.assistant-message{padding:22px 0;border-bottom:1px solid var(--aito-line)}.assistant-message__by{display:flex;align-items:center;gap:8px;color:var(--aito-muted);font-size:12px;margin-bottom:10px}.assistant-message__by .q-icon{color:var(--aito-accent);font-size:17px}.assistant-message__by time{margin-left:auto;font-size:10px}.assistant-message__content{font-size:14px;line-height:1.8;color:var(--aito-text);overflow-wrap:anywhere;min-width:0}.assistant-message--user .assistant-message__content{padding:13px 17px;border-radius:15px 15px 4px 15px;background:var(--aito-panel);margin-left:35px}.assistant-message--user .assistant-message__by{padding-left:35px}.assistant-prose{white-space:pre-wrap}.assistant-prose :deep(h3){font-size:18px;font-weight:700;line-height:1.4;margin:18px 0 8px}.assistant-prose :deep(h4){font-size:15px;font-weight:700;line-height:1.4;margin:15px 0 6px}.assistant-prose :deep(a){color:var(--aito-accent);text-decoration:underline}.assistant-prose :deep(code){background:var(--aito-tint);padding:2px 5px;border-radius:4px;font-size:12px}.assistant-code{margin:15px 0;border:1px solid var(--aito-line);border-radius:12px;overflow:hidden;background:var(--aito-code,#181a1d)}.assistant-code header{display:flex;align-items:center;gap:4px;padding:7px 10px;background:var(--aito-panel);font-size:11px;color:var(--aito-muted)}.assistant-code header>span{flex:1}.assistant-code .q-btn{font-size:10px}.assistant-code pre{padding:14px;margin:0;white-space:pre;overflow:auto;font-size:12px;line-height:1.6;max-height:400px}.assistant-message__files{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin-top:12px}.assistant-message__copy{opacity:.45;margin-top:8px}.assistant-message__copy:hover{opacity:1}@media(max-width:600px){.assistant-message{padding:18px 0}.assistant-message__content{font-size:13px}.assistant-message--user .assistant-message__content,.assistant-message--user .assistant-message__by{margin-left:0;padding-left:12px}}
</style>
